// SQL-backed HTTP adapter for browser tests. Only localhost disposable Postgres.
import unifiedSandbox from './recurrente-unified-sandbox-succeeded.json' with { type: 'json' };
import http from 'node:http';import {Webhook} from 'svix';import pg from 'pg';import {randomUUID} from 'node:crypto';
const url=process.env.DEIPO_TEST_DATABASE_URL;if(!url||!['127.0.0.1','localhost'].includes(new URL(url).hostname))throw Error('Local test database required');
pg.types.setTypeParser(20,value=>{const n=Number(value);if(!Number.isSafeInteger(n))throw Error('Unsafe fixture bigint');return n;});
pg.types.setTypeParser(1082,value=>value);
const pool=new pg.Pool({connectionString:url});const founder='00000000-0000-4000-8000-000000000001';let current;
const user=()=>({id:founder,aud:'authenticated',role:'authenticated',email:'founder@example.test',app_metadata:{provider:'email'},user_metadata:{},created_at:new Date().toISOString()});
const session=()=>{const n=Math.floor(Date.now()/1000),b=x=>Buffer.from(JSON.stringify(x)).toString('base64url');return {access_token:`${b({alg:'HS256',typ:'JWT'})}.${b({sub:founder,aud:'authenticated',role:'authenticated',iat:n,exp:n+3600})}.c2lnbmF0dXJl`,refresh_token:founder,token_type:'bearer',expires_in:3600,expires_at:n+3600,user:user()};};
async function reset(){current=randomUUID();const n=100000000+Math.floor(Math.random()*100000000);await pool.query(`insert into storage.objects(bucket_id,name) values('drop-assets',$1)`,[`drop-${n}/hero/test.webp`]);await pool.query(`insert into public.drops(id,number,name,slug,capacity,low_stock_threshold,price_minor,pickup_label,hero_image_path,orders_open_at,orders_close_at,fulfillment_date,lifecycle_status,online_ordering_enabled) values($1,$2,'Browser test drop',$3,5,1,17500,'Pickup test',$4,now()-interval '1 day',now()+interval '1 day',current_date+1,'published',true)`,[current,n,'browser-'+current,`drop-${n}/hero/test.webp`]);await pool.query('update public.storefront_config set current_drop_id=$1,next_drop_id=null',[current]);}
await reset();
const rpcArgs={ops_current_role:[],ops_drops:[],sales_desk:['p_drop'],sales_create_draft:['p_drop','p_quantity','p_channel','p_details','p_hash','p_expires'],sales_configure:['p_drop','p_grace','p_tracker','p_reason'],sales_claim:['p_hash','p_session'],customer_claim_access:['p_session','p_hash','p_envelope'],ops_customer_tracker:['p_hash'],sales_rotate_access:['p_id','p_hash','p_envelope','p_expires'],sales_print:['p_id','p_format'],ops_revoke_access:['p_id'],get_storefront_state:[],get_checkout_state:['p_checkout_session_hash'],create_inventory_hold:['p_drop_id','p_quantity','p_checkout_session_hash'],release_inventory_hold:['p_checkout_session_hash'],create_pending_order_from_hold:['p_checkout_session_hash','p_details'],cancel_pending_order:['p_checkout_session_hash'],admin_cancel_pending_order:['p_order_id','p_reason'],prepare_payment_checkout:['p_session_hash','p_sandbox_id'],save_payment_checkout:['p_attempt_id','p_result'],customer_payment_state:['p_session_hash'],receive_payment_webhook:['p_svix_id','p_sha256','p_payload'],process_payment_webhook:['p_event_id','p_sandbox_id']};
http.createServer(async(req,res)=>{const send=(x,status=200)=>{res.writeHead(status,{'Content-Type':'application/json'});res.end(JSON.stringify(x));};const path=new URL(req.url,'http://localhost');try{
 let raw='';for await(const chunk of req)raw+=chunk;const body=raw?JSON.parse(raw):{};
 if(path.pathname==='/provider/test')return send({environment:'sandbox',sandbox_id:'sbx_isolated'});
 if(path.pathname==='/provider/checkouts'){const id='ch_'+randomUUID().replaceAll('-','');return send({id,status:'unpaid',checkout_url:'https://app.recurrente.com/checkout-session/'+id,live_mode:false,sandbox_id:'sbx_isolated',total_in_cents:body.items.reduce((n,i)=>n+i.quantity*i.amount_in_cents,0),currency:'GTQ',expires_at:body.expires_at,payment_method_types:['card','bank_transfer'],bank_transfer_memo:body.bank_transfer_memo},201);}
 if(path.pathname==='/payment-fixture'){
  const a=(await pool.query('select a.*,o.order_code from public.payment_attempts a join public.orders o on o.id=a.order_id join public.inventory_holds h on h.id=o.hold_id where h.drop_id=$1 order by a.created_at desc limit 1',[current])).rows[0];
  if(!a&&!body.payload&&body.raw===undefined)return send({error:'No attempt'},404);
  const status=body.status??'succeeded';const payload=body.payload??(body.raw!==undefined?{}:{event_type:body.eventType??'intent.'+status,id:'in_'+a.id,type:body.type??'payment',status,raw_status:status,amount_in_cents:body.amount??a.amount_minor,currency:body.currency??'GTQ',checkout:{id:body.checkout??a.provider_checkout_id},live_mode:body.live_mode??false,sandbox_id:body.sandbox_id??'sbx_isolated'});
  if(body.unified){
   for(const key of Object.keys(payload))delete payload[key];
   Object.assign(payload,unifiedSandbox,{id:'in_'+a.id,amount_in_cents:a.amount_minor,checkout:{id:a.provider_checkout_id,metadata:{deipo_order_code:a.order_code,deipo_payment_attempt_id:a.id}},payment:{id:'pa_'+a.id}},body.overrides??{});
   if(body.omitSandbox)delete payload.sandbox_id;
  }
  const raw=body.raw??JSON.stringify(payload),id=body.svixId??randomUUID(),time=new Date();
  const signature=new Webhook(process.env.RECURRENTE_WEBHOOK_SECRET).sign(id,time,raw);
  const response=await fetch('http://127.0.0.1:3002/api/webhooks/recurrente',{method:'POST',headers:{'content-type':'application/json','svix-id':id,'svix-timestamp':String(Math.floor(time.getTime()/1000)),'svix-signature':body.invalid?'v1,invalid':signature},body:raw});
  return send({status:response.status,body:await response.json(),svixId:id,inbox:(await pool.query('select event_id,svix_id,provider_intent_id,event_type,processing_status,processing_error from public.payment_webhook_events where svix_id=$1',[id])).rows});
 }
 if(path.pathname==='/payment-stats')return send((await pool.query('select (select count(*) from public.payment_attempts a join public.orders o on o.id=a.order_id join public.inventory_holds h on h.id=o.hold_id where h.drop_id=$1) attempts,(select count(*) from public.payment_webhook_events) inbox',[current])).rows[0]);
 if(path.pathname==='/reset'){await reset();return send({id:current});}
 if(path.pathname==='/delivery-setup'){
 const c=await pool.connect();try{await c.query('begin');
 const full=(await c.query("insert into public.drop_slots(drop_id,starts_at,ends_at,capacity) values($1,'18:00','19:00',1) returning id",[current])).rows[0].id;
 const free=(await c.query("insert into public.drop_slots(drop_id,starts_at,ends_at,capacity,max_units) values($1,'19:00','20:00',2,3) returning id",[current])).rows[0].id;
 const zone=(await c.query("insert into public.drop_delivery_zones(drop_id,code,label,fee_minor) values($1,'z10','Zona 10',0) returning id",[current])).rows[0].id;
 const hash=randomUUID().replaceAll('-','').repeat(2);await c.query('select public.create_inventory_hold($1,1,$2)',[current,hash]);
 await c.query('select public.create_pending_order_from_hold($1,$2)',[hash,{name:'Other synthetic buyer',phone:'+50255551234',method:'pickup',slot_id:full}]);
 await c.query('commit');return send({full,free,zone});}finally{await c.query('rollback');c.release();}
 }
 if(path.pathname==='/commerce-setup'){await pool.query('update public.drops set bank_transfer_grace_seconds=3600,tracker_access_seconds=3600 where id=$1',[current]);return send({id:current});}
 if(path.pathname==='/commerce-stats'){return send((await pool.query(`select (select count(*) from public.assisted_sale_drafts where drop_id=$1) drafts,(select count(*) from public.order_fulfillment f join public.order_items i on i.order_id=f.order_id where i.drop_id=$1) fulfillments,(select f.id from public.order_fulfillment f join public.order_items i on i.order_id=f.order_id where i.drop_id=$1 limit 1) fulfillment_id,(select json_agg(json_build_object('lat',o.delivery_latitude,'lng',o.delivery_longitude,'channel',o.sales_channel)) from public.orders o join public.order_items i on i.order_id=o.id where i.drop_id=$1) orders`,[current])).rows[0]);}
 if(path.pathname==='/close-soon'){await pool.query(`update public.drops set orders_close_at=now()+interval '5 seconds' where id=$1`,[current]);return send({});}
 if(path.pathname==='/disable'){await pool.query('update public.drops set online_ordering_enabled=false where id=$1',[current]);return send({});}
 if(path.pathname==='/stats'){return send((await pool.query(`select (select row_to_json(i) from public.drop_inventory i where drop_id=$1) inventory,(select json_agg(json_build_object('hash',checkout_session_hash,'expires_at',expires_at)) from public.inventory_holds where drop_id=$1) holds`,[current])).rows[0]);}
 if(path.pathname.endsWith('/token'))return send(session());if(path.pathname.endsWith('/user'))return send(user());if(path.pathname.endsWith('/logout'))return send({});if(path.pathname.includes('/.well-known/'))return send({keys:[]});
 if(path.pathname.includes('/rpc/')){const name=path.pathname.split('/').at(-1);if(!(name in rpcArgs))return send({message:'Unavailable'},404);const args=rpcArgs[name].map(k=>body[k]);const c=await pool.connect();try{await c.query('begin');if(['admin_cancel_pending_order','ops_current_role','ops_drops','sales_desk','sales_create_draft','sales_configure','sales_rotate_access','sales_print','ops_revoke_access'].includes(name)){await c.query(`select set_config('request.jwt.claim.sub',$1,true)`,[founder]);await c.query('set local role authenticated');}else if(['prepare_payment_checkout','save_payment_checkout','customer_payment_state','receive_payment_webhook','process_payment_webhook','sales_claim','customer_claim_access','ops_customer_tracker'].includes(name)){if(req.headers.apikey!=='sb_secret_isolated_fixture')throw Error('Service credential required');await c.query('set local role service_role');}else await c.query('set local role anon');const r=await c.query(`select public.${name}(${args.map((_,i)=>'$'+(i+1)).join(',')}) v`,args);await c.query('commit');return send(r.rows[0].v);}catch(e){await c.query('rollback');throw e;}finally{c.release();}}
 const table=path.pathname.split('/').at(-1);
 if(['admin_profiles','admin_order_state','order_items','order_events','drops','drop_inventory','storefront_config','audit_log','payment_attempts','payment_webhook_events'].includes(table)){
  let sql=`select * from public.${table}`,args=[];const conditions=[];
  for(const key of ['id','order_id','user_id','effective_status']){const value=path.searchParams.get(key);if(value?.startsWith('eq.')){args.push(value.slice(3));conditions.push(`${key}=$${args.length}`);}}
  if(table==='admin_order_state'&&!path.searchParams.has('id')){args.push(current);conditions.push(`drop_id=$${args.length}`);}
  if(conditions.length)sql+=' where '+conditions.join(' and ');
  let rows=(await pool.query(sql,args)).rows;if(table==='payment_attempts'&&path.searchParams.has('or'))rows=rows.filter(a=>a.review_reason||a.resolution_status==='review_required'||a.internal_status==='creation_unknown'||(a.internal_status==='creating'&&Date.parse(a.created_at)<Date.now()-45000));if(table==='payment_webhook_events'&&path.searchParams.get('processing_status')?.startsWith('in.'))rows=rows.filter(e=>['received','unmatched','review_required','environment_mismatch'].includes(e.processing_status));if(table==='payment_attempts'){rows=await Promise.all(rows.map(async a=>({...a,orders:(await pool.query('select order_code,inventory_committed_at from public.orders where id=$1',[a.order_id])).rows[0]})));}res.setHeader('Content-Range',`0-${Math.max(0,rows.length-1)}/${rows.length}`);return send(req.headers.accept?.includes('vnd.pgrst.object')?(rows[0]??null):rows);
 }
 return send({message:'Unavailable'},404);
}catch(e){send({message:e.message,code:e.code},400);}}).listen(54329,'127.0.0.1',()=>console.log('Isolated SQL-backed checkout fixture ready'));
